# Texto de la versión final (camera-ready) para ICALTER 2026: inglés, 4 a 6 páginas, un solo autor.
# Responde a los cuatro revisores. Lo usa construir_final.py (funciones P, B, H1, H2, BL, table, figure).
# Las tablas se leen de R/resultados (scripts 11, 13 y 18) para no transcribir números a mano.
import csv
RES = os.path.join(AQUI, '..', 'resultados')
leer = lambda f: list(csv.DictReader(open(os.path.join(RES, f), encoding='utf8')))
f1 = lambda x, n=1: f"{float(x):.{n}f}"
ic = lambda a, b, n=3: f"{f1(a, n)}–{f1(b, n)}"

BENCH = {r['modelo']: r for r in leer('13_benchmarks.csv')}
NOMBRE_EN = {"XGBoost": "XGBoost", "GAM": "Additive (GAM)", "Bosque aleatorio": "Random forest", "Logística": "Logistic",
             "Logística penalizada (elastic net)": "Elastic-net logistic"}
def fila_bench(k):
    r = BENCH[k]
    dif = "ref." if k == "XGBoost" else f"{f1(r['dif_roc_xgb'],3)} ({ic(r['dif_roc_inf'], r['dif_roc_sup'])})"
    return [NOMBRE_EN[k], f"{f1(r['auc_roc'],3)} ({ic(r['auc_roc_inf'], r['auc_roc_sup'])})", f1(r['auc_pr'], 3), f1(r['brier'], 3), dif]
filas_bench = [fila_bench(k) for k in ["XGBoost", "GAM", "Bosque aleatorio", "Logística", "Logística penalizada (elastic net)"]]

RONDA = leer('18_validacion_por_ronda.csv')
def fila_ronda(r):
    adel = "n/a" if not r['adel_auc'] or r['adel_auc'] == 'NA' else f"{f1(r['adel_auc'],3)} ({ic(r['adel_inf'], r['adel_sup'])})"
    pred = "n/a" if not r['adel_pred'] or r['adel_pred'] == 'NA' else f1(r['adel_pred'])
    return [r['ronda'], f"{int(r['n']):,}", f1(r['prevalencia']), f"{f1(r['loro_auc'],3)} ({ic(r['loro_inf'], r['loro_sup'])})", adel, pred]
filas_ronda = [fila_ronda(r) for r in RONDA]
adel = [r for r in RONDA if r['adel_auc'] not in ('', 'NA')]
ADEL_MIN, ADEL_MAX = min(float(r['adel_auc']) for r in adel), max(float(r['adel_auc']) for r in adel)
LORO_MIN, LORO_MAX = min(float(r['loro_auc']) for r in RONDA), max(float(r['loro_auc']) for r in RONDA)
R25 = [r for r in RONDA if r['ronda'] == '2025'][0]
SOBRE = [float(r['adel_pred']) - float(r['prevalencia']) for r in adel]

EQ = {r['region']: r for r in leer('18_equidad_region.csv')}
REG_EN = [("Costa", "Coast"), ("Sierra", "Highlands"), ("Selva", "Rainforest")]
CAND = leer('18_candidatos_region.csv')[0]
AC = {(r['costos'], r['regla']): r for r in leer('18_asignacion_costos.csv')}
def pct_reg(regla, reg, costos='uniforme'): return f1(AC[(costos, regla)][reg], 0)
filas_eq = [[en, f1(EQ[es]['observada']), f1(EQ[es]['predicha']), f1(EQ[es]['auc'],3),
             f1(EQ[es]['recall'],0), f1(CAND[es],0), pct_reg('probabilidad', es), pct_reg('ganancia', es)] for es, en in REG_EN]
def nuevo(costos, regla):
    r = AC[(costos, regla)]; return f"{round(float(r['nuevos']))} ({round(float(r['inf']))}–{round(float(r['sup']))})"
REGLAS = [("probabilidad", "Highest probability"), ("ganancia", "Largest simulated gain"), ("ganancia_costo", "Gain per unit cost"), ("azar", "Random")]
filas_asig = [[en, nuevo('uniforme', k), f1(AC[('uniforme', k)]['costo_por_nuevo']), str(round(float(AC[('regional', k)]['productores']))),
               nuevo('regional', k), f1(AC[('regional', k)]['costo_por_nuevo'])] for k, en in REGLAS]
NU = lambda c, k: round(float(AC[(c, k)]['nuevos']))
CPN = lambda c, k: f1(AC[(c, k)]['costo_por_nuevo'])
HR = lambda k, c='uniforme': f1(float(AC[(c, k)]['Sierra']) + float(AC[(c, k)]['Selva']), 0)

TITLE = "Prescriptive Analysis of Agricultural Credit Access in Peru Using Gradient Boosting and Explainable Machine Learning"
c = []
c.append('<w:p><w:pPr><w:pStyle w:val="Abstract"/><w:rPr><w:i/><w:iCs/></w:rPr></w:pPr><w:r><w:rPr><w:i/><w:iCs/></w:rPr><w:t>Abstract</w:t></w:r><w:r><w:t xml:space="preserve">—'
 + escape("Only about one in ten small and medium agricultural producers in Peru obtains credit. With 49,837 producers from seven rounds of the National Agricultural Survey (2016 to 2025), we model whether a producer applied for and obtained credit and use the model to decide whom a budget-limited program should reach. Fourteen of 35 candidate predictors were kept. On sampling clusters not used for training, XGBoost reached an area under the ROC curve of 0.798 (95% interval 0.780 to 0.814), "
          f"between {ADEL_MIN:.3f} and {ADEL_MAX:.3f} when each survey round was predicted only from earlier rounds, and 0.801 on all 196,566 cleaned producers. An additive model and a logistic regression were within 0.007, so the survey information, not the algorithm, limits accuracy. Access depends mainly on applying: 13 percent of producers applied and 92 percent of applicants obtained credit. "
          "The top 20 percent of producers by predicted probability contains 54 percent of credit holders, and producers with a high predicted probability but no credit almost never applied (2 percent). "
          f"For a program that promotes association membership, choosing producers by predicted probability yields about {NU('uniforme','probabilidad')} expected new credit holders per 1,000 producers served, against {NU('uniforme','azar')} at random, but concentrates the program on the coast; choosing by simulated gain reaches more highland and rainforest producers at a cost of about 10 percent fewer new holders. "
          "All scenario estimates are conditional predictions of the model, not causal effects.")
 + '</w:t></w:r></w:p>')
c.append(P('Keywords', "Keywords—agricultural credit, financial inclusion, explainable machine learning, SHAP, budget-constrained targeting, survey data"))

c.append(H1("Introduction"))
c.append(B("Access to credit allows agricultural producers to buy inputs, adopt technology and absorb shocks, yet formal credit reaches only a minority of small farms in developing countries. In Peru the agrarian credit market has been described as incomplete [[wiener]], and household studies show that credit constraints lower farm productivity and that many producers who could qualify do not apply because of the risk involved [[guirkinger,boucher]]. Explanatory studies with the national survey found that being a smallholder reduces access to credit [[ramos24]] and that association membership doubles the odds of requesting credit among coffee farmers [[paredes]]."))
c.append(B("Machine learning adds prediction. Gradient boosting captures nonlinear relations in tabular data [[chen]], and SHAP values make its predictions interpretable [[lundberg17]]. It has been used to predict financial inclusion in Peru [[maehara]], credit constraints of rural households in China [[liu]] and credit scores of smallholders in India [[jonnalagadda]], while farm-survey evidence shows that it does not always beat standard models [[ifft]]. These studies predict or explain access but rarely use the model to support a decision. Prescriptive analytics seeks the best course of action [[lepenioti]], and machine learning has been used to target social assistance under a fixed budget [[aiken]]."))
c.append(B("We contribute in three ways. First, we show with survey questions on applications that the producers who resemble borrowers but lack credit did not apply, so the barrier lies before the application. Second, we validate the model across sampling clusters, survey rounds and regions, and compare it with simpler models. Third, we frame the prescriptive part as a budget-constrained targeting problem, evaluated with independent models and with intervention costs, and we report its regional equity. The work was carried out as an open and reproducible project of a university data science course, with R, Quarto and a public dashboard, so it also serves as a teaching case of predictive and prescriptive analytics with public survey data."))

c.append(H1("Data and Methods"))
c.append(H2("Data, Outcome and Harmonization"))
c.append(B("The National Agricultural Survey (ENA) of the National Institute of Statistics and Informatics [[inei]] is an annual two-stage survey: INEI selects small areas, which we call clusters (groups of dwellings until 2022 and map segments from 2023), and interviews the producers in each. We kept small and medium producers in seven rounds: 2016, 2017, 2019 and 2022 to 2025. The 2014, 2015 and 2018 rounds lack area and parcel variables, there was no survey in 2020, and the 2021 round has no credit module. The rounds were harmonized by variable name (1,324 of the 1,329 variables of 2025 keep their name since 2014), areas were taken only in hectares, and records that come one per crop, parcel or household member were reduced to one row per producer and year."))
c.append(B("The ENA asks whether the producer applied for credit in the previous 12 months (question P901) and whether it was obtained (P902). The outcome equals one when the producer applied and obtained credit from any lender. In the sample 13.0 percent applied and 91.9 percent of applicants obtained credit, and 95 percent of credit holders borrowed from at least one formal or semiformal lender."))
c.append(B("Eight consistency rules, such as an age below 18, a harvested area above three times the total area or a missing predictor, removed 20,969 of 217,535 records; nothing was imputed. The removed records had a lower credit rate (6.4 against 11.8 percent), mostly because they had no harvest or livestock, so the results refer to active producers with complete records. From the 196,566 cleaned producers we drew whole clusters at random within each year and natural region (Table I) and adjusted the expansion factors, so the weighted credit rate is 10.13 percent in the sample against 10.10 percent in the population. Training and test sets were split by cluster, because a split that ignores the dependence between neighbors leaks information [[kapoor,ploton]]. Models are fitted without weights, as usual for prediction; every population rate is weighted and labeled as such."))
c.append(table("Construction of the Modeling Sample", ["Step", "Producers", "Clusters", "Credit (%)"],
   [["Study population (7 rounds)", "217,535", "n/a", "11.2"], ["Cleaned population", "196,566", "29,498", "11.8"], ["Modeling sample", "49,837", "7,491", "11.9"],
    ["Training / test sets", "39,868 / 9,969", "6,005 / 1,486", "11.9 / 11.9"]], [100, 58, 52, 40],
   "Unweighted rates. The weighted national credit rate is 10.1 percent."))
c.append(H2("Predictors and Models"))
c.append(B("Thirty-five candidates describe the producer, the farm, practices, market links, association membership, natural region and department. Using only the training set, we ranked them by mean absolute SHAP value in five-fold cross-validation grouped by cluster, removed the less important variable of each pair with a Spearman correlation of 0.70 or more, and kept the smallest set within one standard error of the best cross-validated performance [[hastie]], which gave 14 predictors."))
c.append(B("XGBoost [[chen]] was tuned through caret [[kuhn]] by random search over 40 combinations of nine hyperparameters, with the area under the precision-recall curve (AUC-PR) as criterion because credit holders are a minority [[saito]]. The selected model has 604 trees, a learning rate of 0.0235, a maximum depth of 6, a minimum child weight of 4.8, row and column subsampling of 0.62 and 0.57, a minimum loss reduction of 4.08, and L2 and L1 penalties of 0.16 and 0.22. The threshold of 0.175 maximizes the F1 score out of fold. We compared it with a logistic regression, an elastic-net logistic regression [[friedman10]], a random forest of 500 trees [[wright]] and a generalized additive model [[wood]] fitted to the same predictors, and used the test set once."))
c.append(H2("Validation"))
c.append(B("We computed 95 percent intervals for test metrics and for differences between models from 1,000 bootstrap resamples of test clusters, and estimated the calibration slope and intercept. To assess generalization in time we predicted each complete survey round with a model trained only on the earlier rounds, and also left out one round at a time. To assess regional equity we compared discrimination, calibration and recall across the three natural regions, and we left out one region at a time. Finally, we refitted the model with grouped cross-validation on all 196,566 cleaned producers."))
c.append(H2("Budget-Constrained Targeting"))
c.append(B("We frame the prescriptive question as an allocation problem. A program can promote association membership, the condition most associated with credit, among producers who are neither members nor borrowers. For each candidate, the model gives a calibrated probability and a simulated gain: the change in predicted probability when membership is switched on and every other variable is kept as observed. The gain is a conditional prediction of the model, not a causal effect. We compared four rules: highest predicted probability, largest simulated gain, largest gain per unit cost, and random choice. Because a model that selects producers also overrates them, we used cross-fitting: two models trained on disjoint halves of the training clusters take turns to select and to evaluate, averaged over five random splits, with intervals from bootstrap resamples of test clusters. We considered a uniform cost and an illustrative regional cost of 1, 1.5 and 2 units per producer on the coast, in the highlands and in the rainforest, reflecting the greater dispersion of producers; the budget is 1,000 units."))
c.append(B("We also report, as conditional predictions, the mean predicted rate when each of four actionable conditions (association membership, sales to regional or Lima markets, irrigation on all crops and fertilizer use) is switched on for the producers who lack it."))

c.append(H1("Results"))
c.append(H2("Predictive Performance and Validation"))
c.append(B("On the test set XGBoost reaches an AUC-ROC of 0.798 and an AUC-PR of 0.367, three times the prevalence of 0.119, with a recall of 59 percent and a precision of 30 percent at the threshold. It is well calibrated: the calibration slope is 1.04, the intercept -0.04, and in the top decile the mean prediction is 42.0 percent against 42.7 percent observed. Table II shows that the other models come close. XGBoost exceeds the logistic regressions by 0.007 in AUC-ROC, a difference whose interval excludes zero but is too small to matter in practice, and it does not differ from the additive model. With all 196,566 cleaned producers the cross-validated AUC-ROC is 0.801."))
c.append(table("Comparison of Models on the Test Set (9,969 Producers)", ["Model", "AUC-ROC (95% CI)", "AUC-PR", "Brier", "XGBoost minus model (95% CI)"],
   filas_bench, [64, 60, 30, 30, 70], "Intervals: 1,000 bootstrap resamples of test clusters. All models use the same 14 predictors and training set."))
c.append(B(f"Table III reports the validation by round. Predicting each complete round only from earlier rounds gives AUC-ROC values between {ADEL_MIN:.3f} and {ADEL_MAX:.3f}; the lowest value comes from 2017, predicted with 2016 alone. Trained on 2016 to 2024, the model reaches {float(R25['adel_auc']):.3f} on the 2025 round. Leaving out one round at a time gives {LORO_MIN:.3f} to {LORO_MAX:.3f}. Ranking is therefore stable over time, but the level of the predictions is not: because the credit rate fell after 2016, a model trained on earlier rounds overpredicts the next one by {min(SOBRE):.1f} to {max(SOBRE):.1f} points, so the model should be recalibrated with each new round."))
c.append(table("Validation by Survey Round", ["Year", "n", "Rate (%)", "Round left out", "Earlier rounds only", "Pred. (%)"],
   filas_ronda, [28, 32, 30, 62, 62, 32],
   "AUC-ROC with 95% intervals from bootstrap resamples of clusters. Round left out: trained on the other six rounds. Earlier rounds only: trained on all previous rounds. Rate: observed credit rate. Pred.: mean prediction of the earlier-rounds model."))
c.append(H2("Factors Associated with Credit"))
c.append(B("Fig. 1 ranks the predictors by mean absolute SHAP value. Harvested area is the most important, followed by age, department, household size and fertilizer use. The logistic regression agrees in direction: association members have about twice the odds of holding credit (odds ratio 2.12; cluster-robust 95 percent interval 1.89 to 2.37), the odds rise with harvested area and fertilizer use, and they fall with age. The relation is close to additive, which is why simpler models perform alike."))
c.append(figure('fig1_shap.png', "Importance of the 14 selected predictors (mean absolute SHAP value, test set).", 2.5, 3.2))
c.append(H2("Potential Access and Effective Demand"))
c.append(B("Ranking by predicted probability concentrates credit: the top 10 percent of test producers contains 36 percent of credit holders and the top 20 percent contains 54 percent. The model also flags 16.4 percent of producers who have no credit but a probability above the threshold. These producers have the potential profile of a borrower, but the survey shows that they are not an unmet demand: only 1.9 percent of them applied, against 0.7 percent of the remaining producers without credit. Potential access therefore differs from effective demand, and the barrier lies before the application. This group is largest where credit is already common, such as Tumbes (46.7 percent of producers), Lambayeque (33.8) and Tacna (33.4), and smallest in Loreto (1.6), and it follows the department credit rate closely (Spearman correlation 0.98)."))
c.append(B("Lenders matter for this pattern. Public lending, mainly Agrobanco, fell from 2.0 to 0.6 borrowers per 100 producers between 2017 and 2019, during the financial crisis of the bank [[agrobanco]], and recovered to 2.5 in 2025. Other lenders did not take its clients: among producers with the profile of Agrobanco clients, borrowing from other lenders stayed at about 13 percent while total access fell from 18.2 to 14.3 percent. Public lenders reach association members more often than private lenders do (odds ratio 2.33; 95 percent interval 2.09 to 2.61)."))
c.append(H2("Regional Equity"))
c.append(B(f"Table IV compares the regions. Discrimination is similar, with overlapping intervals (AUC-ROC from {min(float(EQ[k]['auc']) for k in EQ):.3f} to {max(float(EQ[k]['auc']) for k in EQ):.3f}), and predicted and observed rates agree on the coast and in the highlands, while the rainforest is overpredicted by {float(EQ['Selva']['predicha'])-float(EQ['Selva']['observada']):.1f} points. A single national threshold, however, identifies {f1(EQ['Costa']['recall'],0)} percent of coastal credit holders but only {f1(EQ['Sierra']['recall'],0)} percent of those in the highlands, because the base rate is lower there. When a whole region is left out of training, AUC-ROC falls to between 0.730 and 0.779. Ranking by probability is therefore efficient but not neutral: it favors the coast, where {f1(CAND['Costa'],0)} percent of the candidates live but {pct_reg('probabilidad','Costa',)} percent of those selected by probability are located."))
c.append(table("Regional Performance and Composition of the Selected Producers", ["Region", "Obs. (%)", "Pred. (%)", "AUC-ROC", "Rec. (%)", "Cand. (%)", "Prob. (%)", "Gain (%)"],
   filas_eq, [50, 28, 28, 32, 30, 28, 28, 28],
   "Test set (coast 2,104, highlands 5,732 and rainforest 2,133 producers). Obs. and Pred.: observed and mean predicted credit rate. Rec.: recall at the 0.175 threshold. Cand.: share of the non-member producers without credit. Prob. and Gain: share of the producers selected with a budget of 1,000 and uniform costs."))
c.append(H2("Budget-Constrained Targeting"))
c.append(B(f"Table V gives the expected new credit holders, according to an independent model, when association is promoted with a budget of 1,000 units. With uniform costs, choosing by predicted probability yields {NU('uniforme','probabilidad')} new holders, choosing by simulated gain {NU('uniforme','ganancia')}, and random choice {NU('uniforme','azar')}. The probability rule is the most efficient, at {CPN('uniforme','probabilidad')} cost units per new holder, but the gain rule places {HR('ganancia')} percent of the program in the highlands and the rainforest, against {HR('probabilidad')} percent for the probability rule. With higher costs in the highlands and the rainforest, the best rules shift toward the coast, and the gain-per-cost rule reaches only {pct_reg('ganancia_costo','Selva','regional')} percent of its producers in the rainforest. The choice between rules is therefore a choice between efficiency and regional equity that a program has to make explicitly."))
c.append(table("Expected New Credit Holders with a Budget of 1,000 Units", ["Rule", "Uniform: new (95% CI)", "Cost per new", "Served", "Regional: new (95% CI)", "Cost per new"],
   filas_asig, [60, 52, 28, 32, 52, 28],
   "Promotion of association among non-members without credit (test set). Uniform: same cost for every producer. Regional: served is the number of producers the budget covers. One cross-fitted model selects and an independent model evaluates, averaged over five splits. Regional costs: 1, 1.5 and 2 units on the coast, highlands and rainforest (illustrative)."))
c.append(H2("Conditional Scenarios"))
c.append(B("If the producers who lack each condition had it, with everything else as observed, the mean predicted rate would rise from 12.3 percent (10.3 weighted) to 18.7 percent for association membership (95 percent interval 17.8 to 19.6; 16.4 weighted), 13.8 for irrigation, 13.5 for market sales and 13.4 for fertilizer use; the four together give 25.1 percent (24.2 to 26.0). Because 93 percent of producers are not members and the conditions occur together, these figures extrapolate from the data and ignore how one condition would change the others; they are conditional predictions, not effects of an intervention, and their intervals do not include the uncertainty of the model."))

c.append(H1("Discussion"))
c.append(B("The results matter for three decisions. For a lender that wants to place credit efficiently, a simple ranking by predicted probability concentrates 54 percent of borrowers in 20 percent of producers, and an additive model or a logistic regression does this as well as XGBoost (differences of 0.007 in AUC-ROC or less), so the more transparent model can be preferred [[rudin]]. For a program that wants new borrowers, the relevant group is not an unmet demand of rejected applicants: fewer than 2 percent of the high-propensity producers without credit applied, and 92 percent of applicants obtain credit, so outreach that lowers the cost of applying, such as information, simpler procedures or products linked to producer organizations, is the response to test. For the allocation of a fixed budget, the most efficient rule favors the coast, while a rule that spreads the program to the highlands and the rainforest costs about one in ten expected new borrowers; this trade-off, and not a single optimal list, is what the model can offer to a decision maker."))
c.append(B("The link with association membership is consistent across models and with census evidence [[paredes]], and public lenders reach members more often. But members may join in order to borrow, and better-off producers may be more likely to do both, so the association can run in several directions. Model-agnostic interpretations can mislead when read causally or when predictors are dependent [[molnar]]. The scenarios and the targeting rules therefore indicate where to pilot a program; the size of its effect should be estimated with experimental or quasi-experimental designs, such as matching [[paredes]] or causal forests [[wager]]."))
c.append(B("The study has further limitations. The consistency rules removed producers with lower credit rates; precision is 0.30, so the model suits the prioritization of groups rather than individual decisions; the predictions drift in level between rounds and should be recalibrated; the regional costs are illustrative; and the survey has no supply-side information, such as the distance to lenders, nor the reasons for not applying."))

c.append(H1("Conclusions"))
c.append(B(f"Fourteen survey variables rank Peruvian small and medium producers by their likelihood of holding credit with an AUC-ROC of 0.798 (0.780 to 0.814), stable when each survey round is predicted from earlier ones ({ADEL_MIN:.3f} to {ADEL_MAX:.3f}) and similar across regions, and simpler models perform within 0.007. Access depends on applying: 13 percent applied and 92 percent of them obtained credit, while only 1.9 percent of the 16.4 percent of producers with a high predicted probability and no credit applied. For a program that promotes association with a fixed budget, ranking by probability yields {NU('uniforme','probabilidad')} expected new borrowers per 1,000 producers against {NU('uniforme','azar')} at random, and a gain-based rule trades about 10 percent of that efficiency for a wider regional reach. These are conditional predictions; future work should measure why producers do not apply, add supply-side data and evaluate association-based credit with causal designs."))

c.append(P('Heading5', "Data and Code Availability"))
c.append(B("The modeling sample, the R scripts, a Quarto report that recomputes every figure, and the result tables are available at github.com/ROBERTHGONZALES/credito-agro-ena-r, and an interactive dashboard with the results for each department is available at roberthgonzales.github.io/credito-agro-ena-r. The original ENA microdata are published by INEI [[inei]]."))
c.append(P('Heading5', "Acknowledgment"))
c.append(B("The author thanks the National Institute of Statistics and Informatics of Peru for making the survey microdata publicly available and the reviewers for their comments. An artificial intelligence assistant (Claude, Anthropic) was used to support code development and the drafting of the manuscript; the author reviewed all content and is responsible for it."))
c.append(P('Heading5', "References"))
